import{z as p,x as E,o as r,c as d,q as n,j as l,D as s,d as e,s as i,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const N=JSON.parse('{"title":"DNS","description":"","frontmatter":{"title":"DNS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dns.md","filePath":"cs/dns.md","lastUpdated":1791413859000}'),D={name:"cs/dns.md"};function T(c,a,m,C,P,h){const o=E("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;DNS&quot;">​</a></h1><div class="epigraph"><p>域名是层次化的名字；解析器从根到权威逐级询问，得到地址或其他记录。</p><footer>—— 据 Mockapetris, RFC 1034, Domain Names — Concepts and Facilities, 1987 整理</footer></div><p><a href="/cs/quic-contrast">上一课</a>与 TCP 都假定目的是 IP。<a href="/cs/dhcp-nat">DHCP</a> 交出的「DNS 服务器」还没有被使用。人不能记前缀表。缺口是 <strong>DNS</strong>：层次名字到记录（A/AAAA 等）。本课不把 HTTP 方法写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每台主机持有全球静态表，无法更新。RFC 1034：树状名字空间，每区有权威服务器；递归解析器代客户端走路：问根要 TLD，问 TLD 要权威，问权威要记录。常用 <a href="/cs/udp">UDP</a> 53，大包或区传送走 TCP。缺口不是 BGP 如何通告前缀，而是应用看见的名字。</p><p><span class="marginnote">直觉类比：域名像邮政地址，从右往左一级比一级具体——最右的 com 是「大区」，中间的 example 是「城市」，最左的 www 才是「门牌」。DNS 的逐级询问就是按这个层级一层层把信往下转。</span></p><p>本课不把 DNSSEC 验证链写完。</p><p><span class="marginnote">缓存按 TTL。CNAME、MX、NS 是其他记录类型。本课主干是「名字 → 地址」，为 HTTP 打开连接做准备。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用调用解析器库（后课套接字之前）。存根问本地递归；递归从根（或缓存）迭代。应答含答案或转介。与 <a href="/cs/arp">ARP</a> 对照：ARP 是一跳、广播；DNS 是应用层、全球层次、可缓存。</p><p><span class="marginnote">数字实例：DNS 应答塞进 UDP 报文有 512 字节上限，超长会被截断；解析器看到截断标志就改走 TCP 重问。IPv6 和 DNSSEC 让应答变大，后来补了 EDNS0 把上限协商扩到约 4096 字节，但「大包转 TCP」的原则保留。</span></p>',11)),(r(),l(A,null,{default:s(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%20www.example%22%5D%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E8%A7%A3%E6%9E%90%E5%99%A8%22%5D%0A%20%20REC%20--%3E%20ROOT%5B%22%E6%A0%B9%22%5D%0A%20%20ROOT%20--%3E%20TLD%5B%22TLD%22%5D%0A%20%20TLD%20--%3E%20AUTH%5B%22%E6%9D%83%E5%A8%81%22%5D%0A%20%20AUTH%20--%3E%20A%5B%22A%2FAAAA%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("DNS 让 "),t("a",{href:"/cs/ip-subnet"},"IP 编址"),e(" 对人隐藏，让服务可以改地址而不改名字（在 TTL 内）。端到端：解析错误会连错主机，TLS 课才用证书把名字钉到密钥；本课 DNS 本身可被污染，点名即可。Anycast 根与 CDN 的联合在再后一课。")],-1)),(r(),l(A,null,{default:s(()=>[i(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOT%5B%22%E6%A0%B9%E5%8C%BA%20.%22%5D%20--%3E%20COM%5B%22%E5%8C%BA%20.com%20%E7%9A%84%E6%9D%83%E5%A8%81%22%5D%0A%20%20DOT%20--%3E%20ORG%5B%22%E5%8C%BA%20.org%20%E7%9A%84%E6%9D%83%E5%A8%81%22%5D%0A%20%20COM%20--%3E%20EX%5B%22example.com%20%E5%8C%BA%22%5D%0A%20%20EX%20--%3E%20WWW%5B%22www.example.com%22%5D%0A%20%20EX%20--%3E%20MAIL%5B%22mail.example.com%22%5D%0A%20%20NOTE%5B%22%E7%88%B6%E5%8C%BA%E5%8F%AA%E4%BA%A4%E5%87%BA%E6%8C%87%E9%92%88%EF%BC%8C%E7%9C%9F%E7%9B%B8%E5%9C%A8%E5%90%84%E5%8C%BA%E7%9A%84%E6%9D%83%E5%A8%81%22%5D%0A%20%20DOT%20-.-%3E%20NOTE%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">为什么重要：名字与地址解耦，意味着换托管商、换机房甚至换大洲，网址都不用变——只改权威里的 A 记录。反过来，若应用把解析到的 IP 写死在配置里，这层解耦就白做了，迁移时全部跟着改。</span></p><p>查询走 UDP，丢失靠解析器重试，不用 TCP 可靠流，符合「短请求」的端到端选择。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DoH/DoT 的全部部署。不把 mDNS 局域网发现当全球 DNS。也不把 ENUM 电话映射写进主干。解析路径的递归与迭代，下一课拆；得到地址之后，应用层如何取文档，后课 HTTP。</p><p>根与 TLD 的响应是转介不是最终答案；若把转介当 A 记录，客户端会连错。存根解析器不应自己从根走完全程，除非它就是递归器。</p><p>后课默认：主机名可解析为 IP。解析的递归与迭代，下一课；文档的方法、头、状态码，后课 HTTP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DNS（RFC 1034）层次解析名字到记录，UDP 为主。</li><li>缓存 TTL；与 ARP 不在同一层。</li><li>取超文本是 HTTP 的缺口。</li><li>出处：RFC 1034；RFC 1035；Kurose and Ross。</li></ul>',8))])}const S=p(D,[["render",T]]);export{N as __pageData,S as default};
